    render(<HistoryOverlay />);
    // Node label appears as a row
    expect(screen.getByText("Stress")).toBeTruthy();
    // tick=60 at 60 ticks/s → "1s"
    expect(screen.getByText("1s")).toBeTruthy();
  });
});

