    useStore.getState().openAnnotationEditor(id);
    useStore.getState().closeAnnotationEditor();
    expect(useStore.getState().editingAnnotationId).toBeNull();
  });
});

describe("GE-42 addEdge multi-edge", () => {
  beforeEach(() => {
    useStore.setState({
      graph: { ...seedGraph, edges: [] },
      past: [],
      future: [],
    });
  });

  it("second addEdge call on same pair creates a QF edge when a normal edge exists", () => {
    const from = seedGraph.nodes[0].id;
    const to = seedGraph.nodes[1].id;

    useStore.getState().addEdge(from, to); // creates normal
    useStore.getState().addEdge(from, to); // should create QF

    const edges = useStore
      .getState()
      .graph.edges.filter(
        (e) => e.kind === "causal" && e.from === from && e.to === to,
      );
    expect(edges).toHaveLength(2);
    const kinds = edges
      .map((e) => (e.kind === "causal" ? !!e.isQuickFix : null))
      .sort();
    expect(kinds).toEqual([false, true]);
  });

  it("third addEdge call on same pair is a no-op when both variants exist", () => {
    const from = seedGraph.nodes[0].id;
    const to = seedGraph.nodes[1].id;

    useStore.getState().addEdge(from, to); // normal
    useStore.getState().addEdge(from, to); // QF
    useStore.getState().addEdge(from, to); // no-op

    const edges = useStore
      .getState()
      .graph.edges.filter(
        (e) => e.kind === "causal" && e.from === from && e.to === to,
      );
    expect(edges).toHaveLength(2);
  });

  it("second addEdge creates normal when only a QF edge exists", () => {
    const from = seedGraph.nodes[0].id;
    const to = seedGraph.nodes[1].id;

    useStore.getState().addEdge(from, to); // creates normal
    useStore
      .getState()
      .toggleEdgeQuickFix(
        useStore
          .getState()
          .graph.edges.find(
            (e) => e.kind === "causal" && e.from === from && e.to === to,
          )!.id,
      ); // flip to QF
    useStore.getState().addEdge(from, to); // should create normal

    const edges = useStore
      .getState()
      .graph.edges.filter(
        (e) => e.kind === "causal" && e.from === from && e.to === to,
      );
    expect(edges).toHaveLength(2);
    const hasNormal = edges.some((e) => e.kind === "causal" && !e.isQuickFix);
    expect(hasNormal).toBe(true);
  });
});

describe("GE-42 toggleEdgeQuickFix conflict guard", () => {
  beforeEach(() => {
    useStore.setState({
      graph: { ...seedGraph, edges: [] },
      past: [],
      future: [],
    });
  });

  it("toggle is a no-op when the target QF state already exists for the same pair", () => {
    const from = seedGraph.nodes[0].id;
    const to = seedGraph.nodes[1].id;

    useStore.getState().addEdge(from, to); // normal
    useStore.getState().addEdge(from, to); // QF

    const normalEdge = useStore
      .getState()
      .graph.edges.find(
        (e) =>
          e.kind === "causal" &&
          e.from === from &&
          e.to === to &&
          !e.isQuickFix,
      )!;

    useStore.getState().toggleEdgeQuickFix(normalEdge.id); // would duplicate QF — must be no-op

    const edges = useStore
      .getState()
      .graph.edges.filter(
        (e) => e.kind === "causal" && e.from === from && e.to === to,
      );
    expect(edges).toHaveLength(2);
    const hasNormal = edges.some((e) => e.kind === "causal" && !e.isQuickFix);
    expect(hasNormal).toBe(true); // normal edge unchanged
  });
});

describe("GE-41 toggleEdgeQuickFix", () => {
  beforeEach(() => {
    useStore.setState({ graph: seedGraph, past: [], future: [] });
  });

  it("sets isQuickFix: true on a causal edge that has no flag", () => {
    const edge = seedGraph.edges.find((e) => e.kind === "causal")!;
    useStore.getState().toggleEdgeQuickFix(edge.id);
    const updated = useStore
      .getState()
      .graph.edges.find((e) => e.id === edge.id)!;
    expect(updated.kind === "causal" && updated.isQuickFix).toBe(true);
  });

  it("clears isQuickFix when already true", () => {
    const edge = seedGraph.edges.find((e) => e.kind === "causal")!;
    useStore.getState().toggleEdgeQuickFix(edge.id);
    useStore.getState().toggleEdgeQuickFix(edge.id);
    const updated = useStore
      .getState()
      .graph.edges.find((e) => e.id === edge.id)!;
    expect(updated.kind === "causal" && updated.isQuickFix).toBeFalsy();
  });

  it("is a no-op on a constraint edge", () => {
    const graphWithConstraint = {
      ...seedGraph,
      edges: [
        ...seedGraph.edges,
        {
          kind: "constraint" as const,
          constraintKind: "ceiling" as const,
          id: makeEdgeId("c1"),
          from: seedGraph.nodes[0].id,
          to: seedGraph.nodes[1].id,
        },
      ],
    };
    useStore.setState({ graph: graphWithConstraint });
    const constraintEdge = graphWithConstraint.edges.find(
      (e) => e.kind === "constraint",
    )!;
    useStore.getState().toggleEdgeQuickFix(constraintEdge.id);
    const updated = useStore
      .getState()
      .graph.edges.find((e) => e.id === constraintEdge.id)!;
    expect(updated.kind).toBe("constraint");
  });
});

// ─── Modulator store actions ─────────────────────────────────────────────────

describe("addModulator", () => {
  beforeEach(() => {
    useStore.setState({ graph: seedGraph });
  });

  it("adds a modulator to graph.modulators", () => {
    const srcId = seedGraph.nodes[0]!.id;
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    useStore.getState().addModulator(srcId, edgeId, 1);
    expect(useStore.getState().graph.modulators).toHaveLength(1);
    expect(useStore.getState().graph.modulators[0]).toMatchObject({
      from: srcId,
      target: edgeId,
      polarity: 1,
    });
  });

  it("duplicate guard: calling addModulator twice for same from+target returns the existing id", () => {
    const srcId = seedGraph.nodes[0]!.id;
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    const id1 = useStore.getState().addModulator(srcId, edgeId, 1);
    const id2 = useStore.getState().addModulator(srcId, edgeId, 1);
    expect(id1).toBe(id2);
    expect(useStore.getState().graph.modulators).toHaveLength(1);
  });
});

describe("deleteModulator", () => {
  beforeEach(() => {
    useStore.setState({ graph: seedGraph });
  });

  it("removes the modulator with the given id", () => {
    const srcId = seedGraph.nodes[0]!.id;
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    const id = useStore.getState().addModulator(srcId, edgeId, 1);
    useStore.getState().deleteModulator(id);
    expect(useStore.getState().graph.modulators).toHaveLength(0);
  });
});

describe("cascade delete modulators", () => {
  beforeEach(() => {
    useStore.setState({ graph: seedGraph });
  });

  it("deleteNode removes modulators where from === nodeId", () => {
    const srcId = seedGraph.nodes[0]!.id;
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    useStore.getState().addModulator(srcId, edgeId, 1);
    expect(useStore.getState().graph.modulators).toHaveLength(1);
    useStore.getState().deleteNode(srcId);
    expect(useStore.getState().graph.modulators).toHaveLength(0);
  });

  it("deleteEdge removes modulators where target === edgeId", () => {
    const srcId = seedGraph.nodes[0]!.id;
    const edge = seedGraph.edges.find((e) => e.kind === "causal")!;
    useStore.getState().addModulator(srcId, edge.id, 1);
    expect(useStore.getState().graph.modulators).toHaveLength(1);
    useStore.getState().deleteEdge(edge.id);
    expect(useStore.getState().graph.modulators).toHaveLength(0);
  });
});

describe("pending modulator flow", () => {
  beforeEach(() => {
    useStore.setState({ graph: seedGraph });
  });

  it("setPendingModulatorTarget sets the target edge id", () => {
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    useStore.getState().setPendingModulatorTarget(edgeId);
    expect(useStore.getState().pendingModulatorTarget).toBe(edgeId);
  });

  it("confirmModulator creates the modulator and clears pending state", () => {
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    const srcId = seedGraph.nodes[0]!.id;
    useStore.getState().setPendingModulatorTarget(edgeId);
    useStore.getState().confirmModulator(srcId, 1);
    expect(useStore.getState().pendingModulatorTarget).toBeNull();
    expect(useStore.getState().graph.modulators).toHaveLength(1);
  });

  it("cancelModulator clears pending state without creating modulator", () => {
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    useStore.getState().setPendingModulatorTarget(edgeId);
    useStore.getState().cancelModulator();
    expect(useStore.getState().pendingModulatorTarget).toBeNull();
    expect(useStore.getState().graph.modulators).toHaveLength(0);
  });

  it("toggleModulatorPolarity flips polarity from 1 to -1", () => {
    const edgeId = seedGraph.edges.find((e) => e.kind === "causal")!.id;
    const srcId = seedGraph.nodes[0]!.id;
    useStore.getState().setPendingModulatorTarget(edgeId);
    useStore.getState().confirmModulator(srcId, 1);
    const modulator = useStore.getState().graph.modulators[0]!;
    useStore.getState().toggleModulatorPolarity(modulator.id);
    expect(useStore.getState().graph.modulators[0]!.polarity).toBe(-1);
  });
});

